import os
import importlib.util
TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
calculate_cart_total = target.calculate_cart_total


def test_total_plus_tax():
    # 10 + 8.25% tax = 10.825 -> 10.83
    assert calculate_cart_total([10], 0.0825) == 10.83


def test_simple():
    # 100 + 10% tax = 110
    assert calculate_cart_total([100], 0.10) == 110.0


def test_empty_cart():
    assert calculate_cart_total([], 0.0825) == 0.0


def test_multiple_prices():
    # 10 + 20 = 30, +8.25% = 32.475 -> 32.48
    assert calculate_cart_total([10, 20], 0.0825) == 32.48


def test_zero_tax():
    # no tax -> just subtotal
    assert calculate_cart_total([5, 6], 0.0) == 11.0


def test_invalid_negative_price():
    try:
        calculate_cart_total([1, -2], 0.1)
        assert False, "should have raised"
    except ValueError:
        pass


def test_invalid_negative_tax():
    try:
        calculate_cart_total([1, 2], -0.1)
        assert False, "should have raised"
    except ValueError:
        pass

